/* =============================================================
   00_create_source_erp.sql   [GENERATED - อย่าแก้ด้วยมือ]
   จำลองระบบ ERP ต้นทาง (แหล่งข้อมูลที่ 1)

   หมายเหตุ: ทุกคอลัมน์เป็น NVARCHAR โดยตั้งใจ
   เพราะระบบ legacy จำนวนมากเก็บวันที่/ตัวเลขเป็นข้อความ
   ============================================================= */

USE master;
GO
IF DB_ID('SourceERP') IS NULL CREATE DATABASE SourceERP;
GO
USE SourceERP;
GO

IF OBJECT_ID('dbo.ProductionLog') IS NOT NULL DROP TABLE dbo.ProductionLog;
GO
CREATE TABLE dbo.ProductionLog
(
    LogId        INT IDENTITY(1,1) PRIMARY KEY,
    ProdDate     NVARCHAR(50)  NULL,
    DeptName     NVARCHAR(100) NULL,
    ProductCode  NVARCHAR(50)  NULL,
    Shift        NVARCHAR(20)  NULL,
    QtyProduced  NVARCHAR(50)  NULL,
    QtyDefect    NVARCHAR(50)  NULL,
    RunHours     NVARCHAR(50)  NULL,
    OperatorName NVARCHAR(100) NULL,
    CreatedAt    DATETIME2(0)  NOT NULL DEFAULT (SYSDATETIME())
);
GO
CREATE INDEX IX_ProductionLog_Date ON dbo.ProductionLog(ProdDate);
GO

SET NOCOUNT ON;
GO
